/// Return a longest strictly increasing subsequence of nums.
/// A subsequence keeps the original order of the elements it takes but may
/// skip any of them; strictly increasing means every element is greater than
/// the one before it, so equal values never both appear.
/// When several longest strictly increasing subsequences exist, return the
/// one whose list of values is lexicographically smallest (compare the first
/// values, then the second values, and so on). Return an empty vector for an
/// empty input. Values may be negative and may be as large as the i64 range
/// allows; do not rely on sentinel values.
/// >>> longest_increasing_subsequence(vec![3, 1, 2, 1, 8, 5, 6])
/// vec![1, 2, 5, 6]
/// >>> longest_increasing_subsequence(vec![5, 4, 3])
/// vec![3]
fn longest_increasing_subsequence(nums: Vec<i64>) -> Vec<i64> {
    let n = nums.len();
    if n == 0 {
        return Vec::new();
    }
    // best[i]: length of the longest strictly increasing subsequence starting at i
    let mut best = vec![1usize; n];
    for i in (0..n).rev() {
        for j in i + 1..n {
            if nums[j] > nums[i] && best[j] + 1 > best[i] {
                best[i] = best[j] + 1;
            }
        }
    }
    let mut need = *best.iter().max().unwrap();
    let mut out = Vec::new();
    let mut start = 0;
    let mut prev: Option<i64> = None;
    while need > 0 {
        // among positions that can start the rest, take the smallest value,
        // and its earliest position, which leaves the most choices afterwards
        let mut pick: Option<usize> = None;
        for j in start..n {
            let fits = best[j] == need && prev.map_or(true, |p| nums[j] > p);
            if fits && pick.map_or(true, |k| nums[j] < nums[k]) {
                pick = Some(j);
            }
        }
        let k = pick.unwrap();
        out.push(nums[k]);
        prev = Some(nums[k]);
        start = k + 1;
        need -= 1;
    }
    out
}
